/* ===== แก้ 3 บรรทัดนี้ให้ตรงกับหน่วยงาน ===== */
const VET_EMAIL  = 'kwanchanok.d@psu.ac.th';   // อีเมลสัตวแพทย์ที่จะรับแจ้งเตือน
const FROM_EMAIL = 'kwanchanok.d@psu.ac.th';   // ที่อยู่ผู้ส่ง (ต้องตรงกับบัญชีใน credential)
const APP_URL    = 'https://kwanchanokd.github.io/psu-lasc-medicine/';

const b = $input.first().json.body || $input.first().json;
const TH = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];

function thDate(iso) {
  if (!iso) return '-';
  const p = String(iso).split('-');
  if (p.length !== 3) return String(iso);
  const d = new Date(+p[0], +p[1] - 1, +p[2]);
  if (isNaN(d.getTime())) return String(iso);
  return d.getDate() + ' ' + TH[d.getMonth()] + ' ' + (d.getFullYear() + 543);
}
function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c]));
}
function dayDiff(a, c) {
  if (!a || !c) return null;
  const pa = String(a).split('-'), pc = String(c).split('-');
  const da = new Date(+pa[0], +pa[1]-1, +pa[2]), dc = new Date(+pc[0], +pc[1]-1, +pc[2]);
  if (isNaN(da.getTime()) || isNaN(dc.getTime())) return null;
  return Math.round((dc - da) / 86400000);
}

const ref      = b.ref || '(ไม่มีรหัสอ้างอิง)';
const submitted = String(b.createdAt || '').slice(0, 10);
const lead     = dayDiff(submitted, b.startUse);
const items    = Array.isArray(b.items) ? b.items : [];

const TD = 'border:1px solid #999;padding:5px 8px';
const rows = items.map((it, i) =>
  '<tr><td style="' + TD + ';text-align:center">' + (i+1) + '</td>' +
  '<td style="' + TD + '"><b>' + esc(it.name) + '</b></td>' +
  '<td style="' + TD + '">' + esc(it.strength || '-') + '</td>' +
  '<td style="' + TD + ';text-align:right">' + esc(it.qty) + '</td>' +
  '<td style="' + TD + '">' + esc(it.unit || '-') + '</td>' +
  '<td style="' + TD + '">' + esc(it.note || '') + '</td></tr>').join('');

const itemsText = items.map((it, i) =>
  '   ' + (i+1) + '. ' + it.name + (it.strength ? ' (' + it.strength + ')' : '') +
  ' จำนวน ' + it.qty + ' ' + (it.unit || '')).join('\n');

const leadWarn = (lead != null && lead < 14)
  ? '<div style="background:#fdecea;border:1px solid #f5c6cb;color:#9c0006;padding:10px 14px;border-radius:8px;margin:12px 0">' +
    '<b>⚠ ยื่นล่วงหน้าเพียง ' + lead + ' วัน</b> — น้อยกว่าที่ SOP 6.1 กำหนด (14 วัน) อาจจัดหายาไม่ทันวันเริ่มการทดลอง</div>'
  : '';

const head = '<div style="font-family:Sarabun,Tahoma,sans-serif;font-size:14px;color:#2c3e50;max-width:720px">';
const foot = '<p style="font-size:12px;color:#7f8c8d;border-top:1px solid #dfe6ee;padding-top:8px;margin-top:18px">' +
  'อีเมลฉบับนี้ส่งอัตโนมัติจากระบบบริการยาและเวชภัณฑ์ ศูนย์บริการสัตว์ทดลอง มหาวิทยาลัยสงขลานครินทร์ ตาม SOP MED101</p></div>';

/* ---------- อีเมลถึงสัตวแพทย์ ---------- */
const vetHtml = head +
  '<h2 style="color:#0a5f4e;font-size:18px;margin:0 0 4px">มีคำขอซื้อยาและเวชภัณฑ์ใหม่</h2>' +
  '<p style="margin:0 0 12px;color:#7f8c8d">รหัสอ้างอิง <b style="color:#0a5f4e;letter-spacing:1px">' + esc(ref) + '</b></p>' +
  leadWarn +
  '<table style="border-collapse:collapse;width:100%;font-size:13.5px">' +
  '<tr><td style="' + TD + ';background:#f4f6f9;width:190px">นักวิจัยผู้สั่งซื้อยา</td><td style="' + TD + '">' + esc(b.name) + '</td></tr>' +
  '<tr><td style="' + TD + ';background:#f4f6f9">หน่วยงาน / คณะ</td><td style="' + TD + '">' + esc(b.org) + '</td></tr>' +
  '<tr><td style="' + TD + ';background:#f4f6f9">เลขที่ใบอนุญาตใช้สัตว์ทดลอง</td><td style="' + TD + '">' + esc(b.license) + '</td></tr>' +
  '<tr><td style="' + TD + ';background:#f4f6f9">ติดต่อ</td><td style="' + TD + '">' + esc(b.phone) + ' · ' + esc(b.email) + '</td></tr>' +
  '<tr><td style="' + TD + ';background:#f4f6f9">งานวิจัย</td><td style="' + TD + '">' + esc(b.studyNo || '-') + (b.studyTitle ? ' · ' + esc(b.studyTitle) : '') + '</td></tr>' +
  (b.animals ? '<tr><td style="' + TD + ';background:#f4f6f9">สัตว์ทดลองที่ใช้</td><td style="' + TD + '">' + esc(b.animals) + '</td></tr>' : '') +
  '<tr><td style="' + TD + ';background:#f4f6f9">วันที่ยื่น</td><td style="' + TD + '">' + esc(thDate(submitted)) + '</td></tr>' +
  '<tr><td style="' + TD + ';background:#f4f6f9">วันที่เริ่มใช้ยา</td><td style="' + TD + '">' + esc(thDate(b.startUse)) +
    (lead != null ? ' (ล่วงหน้า ' + lead + ' วัน)' : '') + '</td></tr>' +
  (b.tax ? '<tr><td style="' + TD + ';background:#f4f6f9">ออกใบเสร็จในนาม</td><td style="' + TD + '">' + esc(b.bill || b.name) + ' · เลขผู้เสียภาษี ' + esc(b.tax) + '</td></tr>' : '') +
  (b.note ? '<tr><td style="' + TD + ';background:#f4f6f9">หมายเหตุจากผู้ขอ</td><td style="' + TD + '">' + esc(b.note) + '</td></tr>' : '') +
  '</table>' +
  '<h3 style="color:#0a5f4e;font-size:15px;margin:16px 0 6px">รายการยาที่ขอ</h3>' +
  '<table style="border-collapse:collapse;width:100%;font-size:13.5px">' +
  '<tr style="background:#e5f4f0"><th style="' + TD + ';width:34px">ที่</th><th style="' + TD + ';text-align:left">ชื่อยา</th>' +
  '<th style="' + TD + ';text-align:left">ความเข้มข้น</th><th style="' + TD + '">จำนวน</th>' +
  '<th style="' + TD + ';text-align:left">หน่วย</th><th style="' + TD + ';text-align:left">หมายเหตุ</th></tr>' +
  rows + '</table>' +
  '<p style="margin:18px 0 0"><a href="' + APP_URL + '" style="background:#0e7c66;color:#fff;text-decoration:none;padding:10px 20px;border-radius:8px;display:inline-block;font-weight:600">เปิดระบบเพื่อตรวจสอบและรับเข้าระบบ</a></p>' +
  '<p style="font-size:12.5px;color:#7f8c8d;margin-top:10px">คำขอนี้ยังไม่เข้าทะเบียนจนกว่าจะกด “รับเข้าระบบ” ในแท็บ “คำขอเข้าใหม่”</p>' +
  foot;

/* ---------- อีเมลตอบรับถึงนักวิจัย ---------- */
const userHtml = head +
  '<h2 style="color:#0a5f4e;font-size:18px;margin:0 0 10px">ศูนย์บริการสัตว์ทดลองได้รับคำขอของท่านแล้ว</h2>' +
  '<p>เรียน ' + esc(b.name) + '</p>' +
  '<p>ศูนย์บริการสัตว์ทดลอง มหาวิทยาลัยสงขลานครินทร์ ได้รับคำขอซื้อยาและเวชภัณฑ์เพื่อใช้ในงานวิจัยของท่านเรียบร้อยแล้ว</p>' +
  '<div style="text-align:center;border:2px solid #0e7c66;border-radius:10px;padding:12px;margin:16px 0">' +
  '<div style="font-size:12.5px;color:#7f8c8d">รหัสอ้างอิงสำหรับติดตามเรื่อง</div>' +
  '<div style="font-size:24px;font-weight:700;color:#0a5f4e;letter-spacing:2px">' + esc(ref) + '</div></div>' +
  '<h3 style="color:#0a5f4e;font-size:15px;margin:16px 0 6px">รายการที่ท่านขอ</h3>' +
  '<table style="border-collapse:collapse;width:100%;font-size:13.5px">' +
  '<tr style="background:#e5f4f0"><th style="' + TD + ';width:34px">ที่</th><th style="' + TD + ';text-align:left">ชื่อยา</th>' +
  '<th style="' + TD + ';text-align:left">ความเข้มข้น</th><th style="' + TD + '">จำนวน</th>' +
  '<th style="' + TD + ';text-align:left">หน่วย</th><th style="' + TD + ';text-align:left">หมายเหตุ</th></tr>' +
  rows + '</table>' +
  '<h3 style="color:#0a5f4e;font-size:15px;margin:18px 0 6px">ขั้นตอนต่อไป</h3>' +
  '<ol style="padding-left:20px;margin:0">' +
  '<li>สัตวแพทย์ตรวจสอบคำขอ และประสานสถานที่จำหน่ายเพื่อสอบถามราคา</li>' +
  '<li>ท่านจะได้รับ<b>ใบแจ้งค่าใช้จ่ายทางอีเมลฉบับนี้</b></li>' +
  '<li><b>ชำระเงินภายใน 7 วัน</b> นับจากวันที่ได้รับใบแจ้ง — หากเกินกำหนดต้องยื่นคำขอใหม่ (SOP 6.4)</li>' +
  '<li>ศูนย์ฯ จัดซื้อภายใน 7 วันหลังได้รับชำระเงิน (SOP 6.3)</li>' +
  '<li>มารับยาที่เรือนเลี้ยงสัตว์ทดลอง ตรวจสอบชนิด ความเข้มข้น และจำนวน แล้วลงชื่อรับ (SOP 6.7)</li>' +
  '</ol>' +
  '<div style="background:#fdf3e2;border:1px solid #f0c987;color:#7a4f06;padding:10px 14px;border-radius:8px;margin:16px 0">' +
  '<b>ข้อควรทราบ</b> — คำขอนี้ยังไม่ถือว่าได้รับการอนุมัติ จนกว่าสัตวแพทย์จะตรวจสอบและแจ้งค่าใช้จ่ายกลับ<br>' +
  'เมื่อชำระเงินและสัตวแพทย์ดำเนินการซื้อยาแล้ว <b>ไม่สามารถยกเลิกได้ในทุกกรณี</b> (SOP 6.5)</div>' +
  '<p>อีเมลฉบับนี้เป็นการตอบรับอัตโนมัติ กรุณาอย่าตอบกลับ หากมีข้อสงสัยกรุณาติดต่อสัตวแพทย์ประจำเรือนเลี้ยงสัตว์ทดลองโดยตรง</p>' +
  foot;

return [{
  json: {
    ref: ref,
    fromEmail: FROM_EMAIL,
    vetEmail: VET_EMAIL,
    userEmail: b.email || '',
    hasUserEmail: !!b.email,
    vetSubject: '📥 คำขอซื้อยาใหม่ ' + ref + ' — ' + (b.name || '') + (lead != null && lead < 14 ? ' [ยื่นกระชั้น ' + lead + ' วัน]' : ''),
    userSubject: 'ตอบรับคำขอซื้อยาและเวชภัณฑ์ ' + ref + ' — ศูนย์บริการสัตว์ทดลอง ม.อ.',
    vetHtml: vetHtml,
    userHtml: userHtml,
    itemsText: itemsText,
    submitted: submitted,
    lead: lead
  }
}];
